   CanPayCosts(who = $, lTargets = $)
   {
      local  oTarget, oRoom;

      oTarget = First(lTargets);

      % Check (and deny) casting on yourself.
      if who = oTarget
      {
         Send(who,@MsgSendUser,#message_rsc=summonEvilTwin_no_self);

         return FALSE;
      }

      % Don't cast on non-players or morphed players.
      if NOT IsClass(oTarget,&Player)
         OR Send(oTarget,@CheckPlayerFlag,#flag=PFLAG_MORPHED)
      {
         Send(who,@MsgSendUser,#message_rsc=summonEvilTwin_bad_target,
              #parm1=Send(First(ltargets),@GetDef),
              #parm2=Send(First(ltargets),@GetName));
            
         return FALSE;
      }
      else
      {
         % Is a player.  Check for valid attack.
         if NOT Send(who,@AllowPlayerAttack,#victim=oTarget)
         {
            return FALSE;
         }
      }

      oRoom = Send(SYS,@UtilGetRoom,#what=who);

      if Send(oRoom,@CountHoldingHowMany,#class=&Monster) > 25
         OR Send(oRoom,@CountHoldingHowMany,#class=&EvilTwin) > 0
         OR Send(oRoom,@CountHoldingSummoned) > 
            Send(Send(SYS,@GetSettings), @GetPlayerSummonedObjectLimit)
      {
         Send(who,@MsgSendUser,#message_rsc=summonEvilTwin_failed_rsc);
         
         return FALSE;
      }

      propagate;
   }

   CanPayCosts(who = $, lTargets = $, bItemCast = FALSE)
   {
      local target;
      
      % Can cast spell if the 1 target item is a user
      if Length(lTargets) <> 1
      {
         return FALSE;
      }

      % Can cast on any battler (player or monster) unless it's a revenant or supermonster.
      % Casting on a player is just for roleplay.  See CastSpell().

      target = First(lTargets);
      if NOT IsClass(target,&Battler) OR IsClass(target,&Revenant)
               OR IsClass(target,&Lich) OR IsClass(target,&DeadLich)
               OR IsClass(target,&LupoggKing) OR IsClass(target,&Ghost)
               OR IsClass(target,&SpiderQueen) OR IsClass(target,&Brambles)
               OR IsClass(target,&OrcPitBoss) OR IsClass(target,&Yeti)
               OR IsClass(target,&OrcPitBossBody)
      {
         if NOT bItemCast
         {
            Send(who,@MsgSendUser,#message_rsc=spell_bad_target, 
              #parm1=vrName,#parm2=Send(target,@GetDef),#parm3=Send(target,@GetName));
         }
         return FALSE;
      }

      if target = who
      {
         if NOT bItemCast
         {
            Send(who,@MsgSendUser,#message_rsc=spell_no_self_target,#parm1=vrName);
         }
         return FALSE;
      }

      % check for enchantment already applied
      if Send(target,@IsEnchanted,#what=self)
      {
         if NOT bItemCast
         {
            Send(who,@MsgSendUser,#message_rsc=seduce_already_enchanted,
	           #parm1=Send(target,@GetCapDef),#parm2=Send(target,@GetName));
         }
         return False;
      }
      if Send(target,@getMaster) <> $	     %% target has a master already.
      {
         return FALSE;
      }

      propagate;   % Check other things higher up
   }

   CanPayCosts(who = $, lTargets = $, bItemCast = FALSE)
   {
      local oRoom, iRoomNum;

      % Can't cast just after attacking someone
      if Send(who, @GetLastPlayerAttackTime) + 
         Send(Send(SYS, @GetSettings), @TeleportAttackDelaySec) >
         GetTime()
      {
         Send(who, @MsgSendUser, #message_rsc = spell_too_soon_since_attacking);
         return FALSE;
      }         

      if pbCanCastFromAnywhere
      {
         propagate;
      }

      % Can only cast from certain rooms.  This was added because being
      % able to escapt from anywhere was too powerful.

      oRoom = Send(who, @GetOwner);
      iRoomNum = Send(oRoom, @GetRoomNum);

      if (iRoomNum <> RID_TOS AND iRoomNum <> RID_MARION AND
          iRoomNum <> RID_BARLOQUE AND iRoomNum <> RID_CORNOTH AND
          iRoomNum <> RID_JASPER AND iRoomNum <> RID_KOC_INN)
      {
         % In your guild hall?
         if oRoom <> Send(who, @GetGuildHall)
         {
            Send(who, @MsgSendUser, #message_rsc = Elusion_cant_cast_here);
            return FALSE;
         }
      }
      
      propagate;
   }

